//! Chrome/Edge Native Messaging host. Protocol stdout is framed JSON only.
use serde::{Deserialize, Serialize};
use std::{io::{self, Read, Write}, sync::{Arc, Mutex}, thread, time::{Duration, Instant}};
#[cfg(windows)] use windows::Win32::{UI::WindowsAndMessaging::{GetForegroundWindow, GetWindowThreadProcessId}, System::Threading::{OpenProcess, QueryFullProcessImageNameW, PROCESS_QUERY_LIMITED_INFORMATION}};
#[derive(Deserialize)] struct Request { #[serde(rename = "type")] kind: String, #[serde(rename = "sessionId")] session_id: Option<String> }
#[derive(Serialize)] struct Event { #[serde(rename = "type")] kind: &'static str, status: Option<&'static str>, application: Option<String>, #[serde(rename = "awayMs")] away_ms: Option<u128>, #[serde(rename = "sessionId")] session_id: Option<String> }
#[cfg(windows)] fn foreground_app() -> String { unsafe { let hwnd = GetForegroundWindow(); let mut pid = 0; GetWindowThreadProcessId(hwnd, Some(&mut pid)); let process = match OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION, false, pid) { Ok(p) => p, Err(_) => return "unknown".into() }; let mut buf = [0u16; 32768]; let mut size = buf.len() as u32; if QueryFullProcessImageNameW(process, 0, windows::core::PWSTR(buf.as_mut_ptr()), &mut size).is_ok() { String::from_utf16_lossy(&buf[..size as usize]).rsplit('\\').next().unwrap_or("unknown").to_lowercase() } else { "unknown".into() } } }
#[cfg(not(windows))] fn foreground_app() -> String { "unsupported-platform".into() }
fn read_message(input: &mut impl Read) -> io::Result<Option<Request>> { let mut header = [0; 4]; match input.read_exact(&mut header) { Ok(()) => {}, Err(e) if e.kind() == io::ErrorKind::UnexpectedEof => return Ok(None), Err(e) => return Err(e) }; let len = u32::from_le_bytes(header) as usize; if len > 1_048_576 { return Err(io::Error::new(io::ErrorKind::InvalidData, "message too large")); } let mut bytes = vec![0; len]; input.read_exact(&mut bytes)?; serde_json::from_slice(&bytes).map(Some).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e)) }
fn send(output: &Arc<Mutex<io::Stdout>>, event: &Event) -> io::Result<()> { let bytes = serde_json::to_vec(event).map_err(io::Error::other)?; let mut out = output.lock().unwrap(); out.write_all(&(bytes.len() as u32).to_le_bytes())?; out.write_all(&bytes)?; out.flush() }
fn main() {
 let out = Arc::new(Mutex::new(io::stdout())); let active = Arc::new(Mutex::new(false)); let session = Arc::new(Mutex::new(None::<String>));
 { let out = out.clone(); let active = active.clone(); let session = session.clone(); thread::spawn(move || { let mut app = foreground_app(); let mut since = Instant::now(); loop { thread::sleep(Duration::from_secs(1)); if !*active.lock().unwrap() { continue; } let next = foreground_app(); if next != app { let id = session.lock().unwrap().clone(); let _ = send(&out, &Event { kind: "foreground-app", status: None, application: Some(app), away_ms: Some(since.elapsed().as_millis()), session_id: id }); app = next; since = Instant::now(); } } }); }
 let mut input = io::stdin(); loop { match read_message(&mut input) { Ok(Some(req)) => { let id = req.session_id.clone(); match req.kind.as_str() { "start" | "resume" => { *active.lock().unwrap() = true; *session.lock().unwrap() = id.clone(); let _ = send(&out, &Event { kind: "status", status: Some("connected"), application: None, away_ms: None, session_id: id }); }, "pause" => { *active.lock().unwrap() = false; let _ = send(&out, &Event { kind: "status", status: Some("paused"), application: None, away_ms: None, session_id: id }); }, "stop" => { *active.lock().unwrap() = false; let _ = send(&out, &Event { kind: "status", status: Some("stopped"), application: None, away_ms: None, session_id: id }); }, "status" => { let _ = send(&out, &Event { kind: "status", status: Some(if *active.lock().unwrap() { "connected" } else { "paused" }), application: None, away_ms: None, session_id: id }); }, _ => eprintln!("FocusLoop companion rejected unknown command"), } }, Ok(None) => break, Err(err) => { eprintln!("FocusLoop companion protocol error: {err}"); break; } } }
}
